function cleanAndExtractJSON(response) {
    try {
        const result = {
            image_prompt: []
        };

        const lines = response.split('\n');
        let currentPrompt = '';

        for (const line of lines) {
            if (line.includes('"prompt":')) {
                if (currentPrompt) {
                    result.image_prompt.push(currentPrompt.trim());
                }
                currentPrompt = line.split('"prompt":')[1].trim();
            }
        }

        if (currentPrompt) {
            result.image_prompt.push(currentPrompt.trim());
        }

        return { json: result };

    } catch (error) {
        return { 
            json: {
                image_prompt: []
            }
        };
    }
}

const response = $input.first().json.output;
return cleanAndExtractJSON(response);

return $input.first().json.image_prompt.map(prompt => ({
  json: {
    body: {
      prompt: prompt,
  "image_size": {
    "width": $('⚙️ Set Image Parameters').first().json.width,
    "height": $('⚙️ Set Image Parameters').first().json.height
  },
  "num_inference_steps": 12,
  "guidance_scale": 3.5,
  "num_images": 1,
  "enable_safety_checker": true,
}
    }
  }
));

for (let i = 0; i < items.length; i++) {
  items[i].json.fileName = `images_${(i + 1).toString().padStart(3, '0')}.png`;
}
return items;

const now = new Date();
const irishTime = new Date(now.toLocaleString('en-US', { timeZone: 'Europe/Dublin' }));

return [{
  json: {
    date: irishTime.toISOString().split('T')[0],
    dayOfWeek: irishTime.toLocaleDateString('en-IE', { weekday: 'long' }),
    dayOfMonth: irishTime.getDate(),
    month: irishTime.getMonth() + 1,
    monthName: irishTime.toLocaleDateString('en-IE', { month: 'long' }),
    year: irishTime.getFullYear(),
    formattedDate: irishTime.toLocaleDateString('en-IE', { 
      weekday: 'long', 
      year: 'numeric', 
      month: 'long', 
      day: 'numeric' 
    })
  }
}];

